# Surah Hud (chapter 11) — part 7: ayat 61-70 (IDs 1534-1543)
SURAH = 11

ENTRIES = {
1534: (
"اور — ثمود — کی طرف — ان کے بھائی — صالحؑ — کو بھیجا — انہوں نے کہا — اے — میری قوم — اللہ — کی عبادت کرو — اس کے سوا — تمہارا — کوئی معبود — نہیں — اسی — نے — تمہیں — زمین سے پیدا کیا — اور — تمہیں — اس میں — آباد کیا — پس — اس — سے — استغفار کرو — پھر — اس کی طرف — توبہ — کرو — بے شک — میرا رب — قریب — مجیب — ہے",
"""۱۔ صالحؑ — ثمود — کی طرف بھیجے گئے۔
۲۔ ’’وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَالِحًا قَالَ يَا قَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُ هُوَ أَنشَأَكُم مِّنَ الْأَرْضِ وَاسْتَعْمَرَكُمْ فِيهَا فَاسْتَغْفِرُوهُ ثُمَّ تُوبُوا إِلَيْهِ إِنَّ رَبِّي قَرِيبٌ مُّجِيبٌ‘‘ — اور — ثمود — کی طرف — ان کے بھائی — صالحؑ — کو بھیجا — انہوں نے کہا — اے — میری قوم — اللہ — کی عبادت کرو — اس کے سوا — تمہارا — کوئی معبود — نہیں — اسی — نے — تمہیں — زمین سے پیدا کیا — اور — تمہیں — اس میں — آباد کیا — پس — اس — سے — استغفار کرو — پھر — اس کی طرف — توبہ — کرو — بے شک — میرا رب — قریب — مجیب — ہے — یعنی صالحؑ نے کہا — اے — میری قوم — اللہ کی عبادت کرو — اس کے سوا — تمہارا معبود نہیں — اسی نے تمہیں — زمین سے پیدا کیا — اور تمہیں اس میں آباد کیا — استغفار کرو — اور — اس کی طرف — توبہ کرو — میرا رب قریب مجیب ہے۔
۳۔ عملی سبق: اللہ — قریب اور مجیب — ہے؛ توبہ — فوراً — کرو۔"""
),
1535: (
"انہوں نے کہا — اے صالحؑ — آپ — اس سے پہلے — ہمارے — درمیان مقبول — تھے — کیا — آپ — ہمیں — ان چیزوں — کی عبادت سے — روکتے ہیں — جن کی — عبادت ہمارے باپ دادا — کرتے تھے — اور — بے شک — ہم — آپ — کی طرف — ایک — مشتبہ — لاعقلی — میں ہیں",
"""۱۔ ثمود — صالحؑ — کو — پہلے — مقبول گردانتے تھے مگر — اب — شک۔
۲۔ ’’قَالُوا يَا صَالِحُ قَدْ كُنتَ فِينَا مَرْجُوًّا قَبْلَ هَٰذَا أَتَنْهَانَا أَن نَّعْبُدَ مَا يَعْبُدُ آبَاؤُنَا وَإِنَّنَا لَفِي شَكٍّ مِّمَّا تَدْعُونَا إِلَيْهِ مُرِيبٍ‘‘ — انہوں نے کہا — اے صالحؑ — آپ — اس سے پہلے — ہمارے — درمیان مقبول — تھے — کیا — آپ — ہمیں — ان چیزوں — کی عبادت سے — روکتے ہیں — جن کی — عبادت ہمارے باپ دادا — کرتے تھے — اور — بے شک — ہم — آپ — کی طرف — ایک — مشتبہ — لاعقلی — میں ہیں — یعنی انہوں نے کہا — اے صالحؑ — آپ — اس سے پہلے — ہمارے — درمیان — مقبول — تھے — کیا آپ ہمیں — اس چیز کی عبادت سے روکتے ہیں — جو ہمارے باپ دادا — کرتے تھے — اور ہم — آپ کے — بارے میں — مشتبہ — شک — میں — ہیں۔
۳۔ عملی سبق: باپ دادا کی تقلید — حق — کی جگہ — نہیں لے سکتی۔"""
),
1536: (
"انہوں نے کہا — اے — میری قوم — بتاؤ — اگر — میں — اپنے رب کی طرف سے — دلیل — پر ہوں — اور — اس — نے — مجھے — اپنی طرف سے — رحمت — دی — تو — کون — میری مدد — کرے گا — اگر — میں — اس — کی نافرمانی کروں — پس — تم — میرے لیے — صرف — بڑھت — ہو",
"""۱۔ صالحؑ — دلیلِ ربانی — پر ہیں — ضد — بڑھت — کا ہے۔
۲۔ ’’قَالَ يَا قَوْمِ أَرَأَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَۃٍ مِّن رَّبِّي وَآتَانِي مِنْهُ رَحْمَۃً فَمَن يَنصُرُنِي مِنَ اللَّهِ إِنْ عَصَيْتُهُ فَمَا تَزِيدُونَنِي غَيْرَ تَخْسِيرٍ‘‘ — انہوں نے کہا — اے — میری قوم — بتاؤ — اگر — میں — اپنے رب کی طرف سے — دلیل — پر ہوں — اور — اس — نے — مجھے — اپنی طرف سے — رحمت — دی — تو — کون — میری مدد — کرے گا — اگر — میں — اس — کی نافرمانی کروں — پس — تم — میرے لیے — صرف — بڑھت — ہو — یعنی اے میری قوم — بتاؤ — اگر میں اپنے رب کی طرف سے دلیل — پر ہوں — اور وہ مجھے رحمت — دے — تو کون میری مدد کرے گا اگر میں — اس کی نافرمانی کروں — پس — تم — میرے لیے صرف — بڑھت — ہو۔
۳۔ عملی سبق: ضد — نقصان — کا سبب ہے؛ حق — کے سامنے — جھک — جاؤ۔"""
),
1537: (
"اور — اے میری قوم — یہ — اللہ کی اونٹنی ہے — تمہارے لیے — ایک نشانی — پس — اسے کھانے دو — اللہ کی زمین میں — اور — اسے — برائی سے — نہ چھونا — کہ — تمہیں — قریب کا عذاب — پکڑ لے",
"""۱۔ ناقۃ اللہ — ثمود کے لیے نشانی۔
۲۔ ’’وَيَا قَوْمِ هَٰذِهِ نَاقَۃُ اللَّهِ لَكُمْ آيَۃً فَذَرُوهَا تَأْكُلْ فِي أَرْضِ اللَّهِ وَلَا تَمَسُّوهَا بِسُوءٍ فَيَأْخُذَكُمْ عَذَابٌ قَرِيبٌ‘‘ — اور — اے میری قوم — یہ — اللہ کی اونٹنی ہے — تمہارے لیے — ایک نشانی — پس — اسے کھانے دو — اللہ کی زمین میں — اور — اسے — برائی سے — نہ چھونا — کہ — تمہیں — قریب کا عذاب — پکڑ لے — یعنی اے میری قوم — یہ — اللہ کی اونٹنی — ہے — تمہارے — لیے — نشانی؛ اسے اللہ کی زمین میں کھانے دو — اسے برائی سے مت چھونا — کہ تمہیں قریب کا عذاب — پکڑ لے۔
۳۔ عملی سبق: اللہ کی نشانیوں — کا احترام — کرو؛ ورنہ — سزا — قریب — ہے۔"""
),
1538: (
"پس — انہوں نے — اسے — ذبح کر دیا — تو — صالحؑ — نے — کہا — اپنے گھروں میں — تین — دن — لطف — اٹھا لو — یہ — ہے — ایک — وعدہ — جو — جھوٹا — نہیں",
"""۱۔ ناقۃ ذبح — تو — تین دن کی مہلت — اور — پھر — عذاب۔
۲۔ ’’فَعَقَرُوهَا فَقَالَ تَمَتَّعُوا فِي دَارِكُمْ ثَلَاثَۃَ أَيَّامٍ ذَٰلِكَ وَعْدٌ غَيْرُ مَكْذُوبٍ‘‘ — پس — انہوں نے — اسے — ذبح کر دیا — تو — صالحؑ — نے — کہا — اپنے گھروں میں — تین — دن — لطف — اٹھا لو — یہ — ہے — ایک — وعدہ — جو — جھوٹا — نہیں — یعنی انہوں نے — اونٹنی کو ذبح کر دیا — صالحؑ — نے کہا — اپنے گھروں میں — تین — دن — لطف اٹھا لو؛ یہ — ایک — وعدہ — ہے — جو — جھوٹا — نہیں۔
۳۔ عملی سبق: عذاب کی مہلت — قلیل — ہوتی ہے؛ گناہ — فوراً — چھوڑ دو۔"""
),
1539: (
"پس — جب — ہمارا حکم — آیا — تو — ہم — نے — صالحؑ — کو — اور — اس — کے ساتھ ایمان لانے والوں — کو — اپنی رحمت — سے — نجات دی — اور — اس — دن کی رسوائی — سے — بے شک — تمہارا رب — وہ — ہے — غالب باعزت — ہے",
"""۱۔ صالحؑ اور ساتھی — نجات؛ قومِ ثمود — کو — رسوائی کا — دن۔
۲۔ ’’فَلَمَّا جَاءَ أَمْرُنَا نَجَّيْنَا صَالِحًا وَالَّذِينَ آمَنُوا مَعَهُ بِرَحْمَۃٍ مِّنَّا وَمِنْ خِزْيِ يَوْمِئِذٍ إِنَّ رَبَّكَ هُوَ الْقَوِيُّ الْعَزِيزُ‘‘ — پس — جب — ہمارا حکم — آیا — تو — ہم — نے — صالحؑ — کو — اور — اس — کے ساتھ ایمان لانے والوں — کو — اپنی رحمت — سے — نجات دی — اور — اس — دن کی رسوائی — سے — بے شک — تمہارا رب — وہ — ہے — غالب باعزت — ہے — یعنی جب ہمارا حکم آیا — ہم نے صالحؑ — اور — ان — کے ساتھ ایمان لانے والوں — کو — اپنی رحمت سے — اور — اس — دن کی رسوائی — سے نجات دی؛ تمہارا رب — قوی اور عزیز ہے۔
۳۔ عملی سبق: ایمان — اللہ کی حفاظت — میں — ہے۔"""
),
1540: (
"اور — ان — لوگوں کو — جنہوں نے — ظلم — کیا — چیخ — نے — پکڑ لیا — اور — وہ — اپنے گھروں — میں — اوندھے — پڑے — رہ — گئے",
"""۱۔ ظالموں کو — شدید — چیخ — سے — عذاب۔
۲۔ ’’وَأَخَذَ الَّذِينَ ظَلَمُوا الصَّيْحَۃُ فَأَصْبَحُوا فِي دِيَارِهِمْ جَاثِمِينَ‘‘ — اور — ان — لوگوں کو — جنہوں نے — ظلم — کیا — چیخ — نے — پکڑ لیا — اور — وہ — اپنے گھروں — میں — اوندھے — پڑے — رہ — گئے — یعنی ظالموں کو شدید چیخ — نے پکڑ لیا — اور — وہ — اپنے گھروں میں — اوندھے پڑے رہ — گئے۔
۳۔ عملی سبق: ظلم — چیخ — اور — تباہی — کا — سبب ہے۔"""
),
1541: (
"گویا — وہ — وہاں — آباد — ہی نہیں ہوئے تھے — سنو — ثمود — نے — اپنے رب — کی نافرمانی کی — سنو — ثمود — کے لیے — ہلاکت — ہے",
"""۱۔ ثمود — کی بربادی — ایسی — جیسے کبھی آباد — ہی نہ تھے۔
۲۔ ’’كَأَن لَّمْ يَغْنَوْا فِيهَا أَلَا إِنَّ ثَمُودَ كَفَرُوا رَبَّهُمْ أَلَا بُعْدًا لِّثَمُودَ‘‘ — گویا — وہ — وہاں — آباد — ہی نہیں ہوئے تھے — سنو — ثمود — نے — اپنے رب — کی نافرمانی کی — سنو — ثمود — کے لیے — ہلاکت — ہے — یعنی گویا — وہ — وہاں — کبھی آباد ہی — نہیں ہوئے تھے؛ سنو — ثمود — نے اپنے رب — کی نافرمانی کی — سنو — ثمود — کے لیے — ہلاکت — ہے۔
۳۔ عملی سبق: نافرمانی — بستیاں برباد — کر دیتی ہے؛ عبرت — لو۔"""
),
1542: (
"اور — ہم — کے رسول — ابراہیمؑ — کے پاس — خوشخبری — لے کر آئے — انہوں نے — کہا — سلام ہو — انہوں نے — کہا — سلام ہو — پس — ابراہیمؑ — دیر — نہ کی — وہ — بھنا ہوا بچھڑا — لے آئے",
"""۱۔ ابراہیمؑ کے پاس — فرشتے — خوشخبری — لے کر — آئے۔
۲۔ ’’وَلَقَدْ جَاءَتْ رُسُلُنَا إِبْرَاهِيمَ بِالْبُشْرَىٰ قَالُوا سَلَامًا قَالَ سَلَامٌ فَمَا لَبِثَ أَن جَاءَ بِعِجْلٍ حَنِيذٍ‘‘ — اور — ہم — کے رسول — ابراہیمؑ — کے پاس — خوشخبری — لے کر آئے — انہوں نے — کہا — سلام ہو — انہوں نے — کہا — سلام ہو — پس — ابراہیمؑ — دیر — نہ کی — وہ — بھنا ہوا بچھڑا — لے آئے — یعنی ہمارے رسول — ابراہیمؑ — کے پاس — خوشخبری — لے کر آئے — انہوں نے کہا سلام ہو — ابراہیمؑ نے کہا سلام ہو — اور — فوراً — بھنا ہوا بچھڑا — لے آئے۔
۳۔ عملی سبق: مہمان نوازی — مؤمنوں — کا — خلق ہے۔"""
),
1543: (
"پس — جب — انہوں نے — ان — کے ہاتھ — کو — اس — کی طرف — بڑھتے نہ دیکھا — تو — ان — سے ناپسند — کیا — اور — ان — سے — دل میں — خوف — محسوس — کیا — انہوں نے کہا — گھبرائیں نہیں — ہم — لوط — کی قوم — کی طرف — بھیجے گئے ہیں",
"""۱۔ ابراہیمؑ — فرشتوں سے — خوفزدہ — فرشتوں کا جواب۔
۲۔ ’’فَلَمَّا رَأَىٰ أَيْدِيَهُمْ لَا تَصِلُ إِلَيْهِ نَكِرَهُمْ وَأَوْجَسَ مِنْهُمْ خِيفَۃً قَالُوا لَا تَخَفْ إِنَّا أُرْسِلْنَا إِلَىٰ قَوْمِ لُوطٍ‘‘ — پس — جب — انہوں نے — ان — کے ہاتھ — کو — اس — کی طرف — بڑھتے نہ دیکھا — تو — ان — سے ناپسند — کیا — اور — ان — سے — دل میں — خوف — محسوس — کیا — انہوں نے کہا — گھبرائیں نہیں — ہم — لوط — کی قوم — کی طرف — بھیجے گئے ہیں — یعنی جب ابراہیمؑ نے دیکھا کہ — ان کے ہاتھ کھانے کی طرف نہیں بڑھ رہے — تو — ان — سے ناپسند — کیا — اور دل میں خوف — محسوس — کیا — انہوں نے کہا — گھبرائیں نہیں — ہم — لوطؑ — کی — قوم — کی طرف بھیجے گئے ہیں۔
۳۔ عملی سبق: فرشتے — اللہ — کے — حکم سے آتے ہیں؛ خیر — کا — ذریعہ ہیں۔"""
),
}
